from gurobipy import *

def solve_problem():
    m = Model("Battlefield_Logistics")
    m.setParam("TimeLimit", 100)  # Set time limit to 100 seconds

    # Data
    depots = list(range(3))  # D0..D2
    units = list(range(10))  # U0..U9
    supplies = list(range(3))  # S0..S2
    days = list(range(3))  # Day0..Day2

    demands = [[[42.16, 12.58, 37.01], [20.48, 13.54, 11.98], [21.57, 31.44, 43.26]], [[31.13, 15.04, 25.88], [39.39, 10.57, 32.3], [43.92, 34.88, 38.76]], [[45.17, 18.41, 20.51], [42.35, 41.88, 30.89], [10.43, 32.19, 40.79]], [[26.46, 12.84, 47.67], [35.83, 14.97, 18.21], [20.94, 32.15, 27.8]], [[22.6, 15.99, 13.63], [21.63, 28.52, 28.38], [29.19, 49.32, 31.12]], [[48.68, 23.93, 18.92], [31.91, 21.28, 31.75], [36.71, 44.85, 34.02]], [[14.18, 24.95, 12.4], [39.78, 28.95, 20.04], [34.26, 13.41, 42.44]], [[16.44, 39.61, 26.0], [41.59, 37.46, 40.46], [17.41, 30.05, 25.03]], [[14.18, 49.6, 11.83], [31.01, 10.64, 18.88], [14.77, 44.32, 15.65]], [[29.6, 41.35, 35.6], [11.89, 19.89, 49.16], [42.58, 31.49, 36.07]]]
    depot_supplies = [[[118.02, 111.41, 87.09], [139.06, 69.12, 79.89], [112.36, 136.18, 112.49]], [[85.12, 125.64, 87.1], [145.24, 89.85, 118.72], [105.12, 117.58, 156.94]], [[142.8, 99.45, 122.02], [141.92, 90.04, 132.89], [125.79, 98.01, 142.22]]]
    transport_costs = [[1.12, 1.26, 2.53, 3.62, 4.55, 2.34, 3.92, 2.29, 2.97, 4.82], [3.53, 2.37, 2.43, 1.28, 1.83, 3.89, 4.29, 4.86, 4.99, 1.47], [1.83, 4.78, 3.47, 2.21, 2.74, 2.41, 4.78, 3.19, 1.98, 4.62]]
    risk_costs = [[174.3, 60.07, 124.58, 179.22, 126.74, 103.77, 178.82, 157.49, 51.1, 151.54], [129.95, 143.37, 57.66, 195.66, 94.73, 133.31, 82.1, 61.23, 52.92, 181.45], [170.67, 122.36, 121.38, 82.7, 187.69, 60.67, 139.71, 105.57, 165.83, 133.2]]
    supply_volumes = [1.98, 1.32, 0.7]
    penalty_costs = [55.8, 62.33, 96.42]
    vehicle_cost = 10.0
    vehicle_capacity = 139.0
    total_vehicles = 12

    # Decision variables
    # Flow_D{d}_U{u}_S{s}_Day{t}: Amount of supply s from depot d to unit u on day t
    flows = {}
    for t in days:
        for d in depots:
            for u in units:
                for s in supplies:
                    flows[(d, u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Flow_D{d}_U{u}_S{s}_Day{t}")

    # Slack_U{u}_S{s}_Day{t}: Shortage of supply s at unit u on day t
    slacks = {}
    for t in days:
        for u in units:
            for s in supplies:
                slacks[(u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Slack_U{u}_S{s}_Day{t}")

    # Veh_D{d}_U{u}_Day{t}: Number of vehicles on route d->u on day t
    vehicles = {}
    for t in days:
        for d in depots:
            for u in units:
                vehicles[(d, u, t)] = m.addVar(lb=0.0, vtype=GRB.INTEGER, name=f"Veh_D{d}_U{u}_Day{t}")

    # Route_D{d}_U{u}_Day{t}: Route d->u is active on day t (binary)
    routes = {}
    for t in days:
        for d in depots:
            for u in units:
                routes[(d, u, t)] = m.addVar(vtype=GRB.BINARY, name=f"Route_D{d}_U{u}_Day{t}")

    # Objective: Minimize total cost (transport + penalty + vehicle + risk)
    obj = quicksum(
        transport_costs[d][u] * flows[(d, u, s, t)]
        for t in days for d in depots for u in units for s in supplies
    )
    obj += quicksum(
        penalty_costs[s] * slacks[(u, s, t)]
        for t in days for u in units for s in supplies
    )
    obj += quicksum(
        vehicle_cost * vehicles[(d, u, t)]
        for t in days for d in depots for u in units
    )
    obj += quicksum(
        risk_costs[d][u] * routes[(d, u, t)]
        for t in days for d in depots for u in units
    )
    m.setObjective(obj, GRB.MINIMIZE)

    # Depot capacity constraints: Total outflow <= supply
    for t in days:
        for d in depots:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for u in units) <= depot_supplies[d][s][t],
                    name=f"DepotCap_D{d}_S{s}_Day{t}"
                )

    # Demand constraints: Inflow + slack >= demand
    for t in days:
        for u in units:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for d in depots) + slacks[(u, s, t)] >= demands[u][s][t],
                    name=f"Demand_U{u}_S{s}_Day{t}"
                )

    # Vehicle capacity constraints: Total volume <= vehicles * capacity
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    quicksum(supply_volumes[s] * flows[(d, u, s, t)] for s in supplies) <= vehicle_capacity * vehicles[(d, u, t)],
                    name=f"VehCap_D{d}_U{u}_Day{t}"
                )

    # Route activation constraints: vehicles <= total_vehicles * route
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    vehicles[(d, u, t)] <= total_vehicles * routes[(d, u, t)],
                    name=f"RouteAct_D{d}_U{u}_Day{t}"
                )

    # Fleet size constraints: Total vehicles <= total_vehicles
    for t in days:
        m.addConstr(
            quicksum(vehicles[(d, u, t)] for d in depots for u in units) <= total_vehicles,
            name=f"FleetSize_Day{t}"
        )

    m.optimize()
    return m
